"""SendGrid integration template — generates services/email_client.py."""
from __future__ import annotations


def generate_sendgrid_client(output_dir=None, config: dict | None = None) -> str:
    """Return production-ready SendGrid client code as a string."""
    return '''\
"""SendGrid email client — generated by AetherOS p04c_integration_codegen."""
from __future__ import annotations
import asyncio
import logging
import os
from functools import partial
from typing import Any, Dict, List, Optional

logger = logging.getLogger(__name__)


class EmailError(Exception):
    """Base error for email operations."""


class EmailClient:
    """Async SendGrid email client using the sendgrid Python SDK."""

    def __init__(self) -> None:
        self._api_key = os.getenv("SENDGRID_API_KEY", "")
        self._from_email = os.getenv("FROM_EMAIL", "noreply@example.com")
        self._from_name = os.getenv("FROM_NAME", "App")
        if not self._api_key:
            logger.warning("SENDGRID_API_KEY not set — emails will not be sent")

    def _get_sg(self):
        """Lazy-import SendGrid SDK to avoid hard dependency at import time."""
        try:
            from sendgrid import SendGridAPIClient
            return SendGridAPIClient(self._api_key)
        except ImportError as exc:
            raise EmailError("sendgrid package not installed: pip install sendgrid") from exc

    async def send_email(
        self,
        to: str,
        subject: str,
        body: str,
        html_body: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Send a plain-text (and optional HTML) email via SendGrid."""
        if not self._api_key:
            logger.warning("email skipped — SENDGRID_API_KEY not configured")
            return {"status": "skipped", "reason": "no_api_key"}
        try:
            from sendgrid.helpers.mail import Mail, Content
            msg = Mail(
                from_email=(self._from_email, self._from_name),
                to_emails=to,
                subject=subject,
                plain_text_content=body,
            )
            if html_body:
                msg.add_content(Content("text/html", html_body))
            sg = self._get_sg()
            loop = asyncio.get_event_loop()
            response = await loop.run_in_executor(None, partial(sg.send, msg))
            logger.info("email sent to %s status=%s", to, response.status_code)
            return {"status_code": response.status_code, "headers": dict(response.headers)}
        except Exception as exc:
            logger.warning("send_email to %s failed: %s", to, exc)
            raise EmailError(str(exc)) from exc

    async def send_template_email(
        self,
        to: str,
        template_id: str,
        data: Dict[str, Any],
        cc: Optional[List[str]] = None,
    ) -> Dict[str, Any]:
        """Send a transactional email using a SendGrid dynamic template."""
        if not self._api_key:
            logger.warning("template email skipped — SENDGRID_API_KEY not configured")
            return {"status": "skipped", "reason": "no_api_key"}
        try:
            from sendgrid.helpers.mail import Mail, To
            msg = Mail(from_email=(self._from_email, self._from_name))
            msg.to = To(to)
            if cc:
                for addr in cc:
                    msg.add_cc(addr)
            msg.template_id = template_id
            msg.dynamic_template_data = data
            sg = self._get_sg()
            loop = asyncio.get_event_loop()
            response = await loop.run_in_executor(None, partial(sg.send, msg))
            logger.info("template email sent to %s template=%s status=%s",
                        to, template_id, response.status_code)
            return {"status_code": response.status_code}
        except Exception as exc:
            logger.warning("send_template_email to %s failed: %s", to, exc)
            raise EmailError(str(exc)) from exc


email_client = EmailClient()
'''
